const TALING_DICT = new Set([]);

const HAMZAH_DICT = new Set([]);

// Digraf yang dianggap satu konsonan
const ONSETS_DIGRAPH = ["ng","ny","sy","kh","gh","ch"];
// kluster awal Melayu yang sah (2 huruf) — untuk bantu split C* antara vokal
const VALID_CLUSTERS = new Set([
  "bl","br","kl","kr","gl","gr","pl","pr","tr","dr","fl","fr","ch","kh","gh","ng","ny","sy"
]); // only true Malay onset clusters (stop/ fricative + l/r), not st/sp/sk/sm/sn which split as C|C


function isVowel(ch) { return /[aiueoéèê]/.test(ch); }
function normalizeE(word) { return word.replace(/[èê]/g, 'é').replace(/ě/g, 'e'); }

// Helper: is char consonant (single)
function isCons(ch) { return /^[bcdfghjklmnpqrstvwxyz]$/.test(ch); }

// Helper: parse cluster into units (digraph ng/ny/sy/kh/gh/ch counted as one)
function clusterToUnits(cluster) {
  let units = [];
  let i=0;
  while (i<cluster.length) {
    let two = cluster.substr(i,2);
    if (ONSETS_DIGRAPH.includes(two)) { units.push(two); i+=2; }
    else { units.push(cluster[i]); i+=1; }
  }
  return units;
}
function unitsToString(units){ return units.join(''); }

// Syllabify v2 — segmentasi berasaskan posisi vokal + kluster (unit-aware digraph)
function syllabify(word) {
  word = normalizeE(word.toLowerCase());
  if (!word) return [];
  let nuclei = [];
  let i = 0;
  while (i < word.length) {
    let two = word.substr(i,2);
    if (["ai","au","oi","ae"].includes(two)) {
      nuclei.push({start:i, len:2, vowel:two});
      i+=2;
    } else if (isVowel(word[i])) {
      nuclei.push({start:i, len:1, vowel:word[i]});
      i+=1;
    } else {
      i+=1;
    }
  }
  if (nuclei.length === 0) {
    return [{text:word, onset:word, vowel:"", coda:"", isOpen:false, isFirst:true, isLast:true}];
  }
  if (nuclei.length === 1) {
    let n = nuclei[0];
    let onset = word.substring(0, n.start);
    let coda = word.substring(n.start + n.len);
    let isOpen = (coda === "");
    return [{text: onset+n.vowel+coda, onset, vowel:n.vowel, coda, isOpen, isFirst:true, isLast:true}];
  }
  // >=2 nukleus: bahagi antara nukleus menggunakan unit
  let boundaries = [];
  for (let k=0;k<nuclei.length-1;k++) {
    let cur = nuclei[k];
    let nxt = nuclei[k+1];
    let cluster = word.substring(cur.start+cur.len, nxt.start);
    if (cluster === "") {
      boundaries.push(cur.start+cur.len);
      continue;
    }
    let units = clusterToUnits(cluster);
    if (units.length === 1) {
      // V C V -> C onset next
      boundaries.push(cur.start+cur.len);
    } else if (units.length === 2) {
      let combined = units.join('');
      // jika CC valid cluster atau digraf -> keduanya onset
      if (VALID_CLUSTERS.has(combined) || ONSETS_DIGRAPH.includes(combined) || VALID_CLUSTERS.has(units.join(''))) {
        boundaries.push(cur.start+cur.len);
      } else {
        // C|C -> first coda
        let firstUnitLen = units[0].length;
        boundaries.push(cur.start+cur.len+firstUnitLen);
      }
    } else if (units.length >= 3) {
      // V CCC V -> first unit coda, rest onset (e.g., m|bl)
      // Khusus ng cluster: ng|k -> sudah 2 unit tapi di sini 3? actually m b l = 3 units
      let firstLen = units[0].length;
      boundaries.push(cur.start+cur.len+firstLen);
    }
  }
  let syllables = [];
  let prev = 0;
  for (let k=0;k<nuclei.length;k++) {
    let n = nuclei[k];
    let start = prev;
    let end = (k < nuclei.length-1) ? boundaries[k] : word.length;
    let sylText = word.substring(start, end);
    let onset = word.substring(start, n.start);
    let vowel = n.vowel;
    let coda = word.substring(n.start+vowel.length, end);
    let isOpen = (coda === "");
    syllables.push({text:sylText, onset, vowel, coda, isOpen, isFirst:(k===0), isLast:false});
    prev = end;
  }
  if (syllables.length) syllables[syllables.length-1].isLast = true;
  if (syllables.length>1) syllables[syllables.length-2].isPenult = true;
  let cleaned = [];
  for (let s of syllables) {
    if (s.vowel === "" && cleaned.length) {
      cleaned[cleaned.length-1].coda += s.onset + s.coda;
      cleaned[cleaned.length-1].text += s.text;
    } else cleaned.push(s);
  }
  cleaned.forEach((s, idx)=>{ s.isFirst = idx===0; s.isLast = idx===cleaned.length-1; s.isOpen = s.coda===""});
  return cleaned;
}

// ---------- 4. Pepet vs Taling ----------
function isTaling(globalWord, syl) {
  if (syl.vowel === 'é') return true;
  if (syl.vowel !== 'e') return false;
  if (TALING_DICT.has(globalWord)) return true;
  if (TALING_DICT.has(syl.text)) return true;
  // Rule-based taling v9 (data PRPM, tanpa kamus — TALING_DICT kekal 0):
  // R1: e + coda k/g/j/h/t/s/ng/l/y pada suku TERAKHIR → taling (objek, tiket, proses, loceng, comel, imej, teh, oleh)
  if (syl.isLast && ['k','g','j','h','t','s','ng','l','y'].includes(syl.coda)) return true;
  // R2: e + coda n dengan onset b/s/p → taling (sen, stesen, besen, cerpen)
  if (syl.coda==='n' && ['b','s','p'].includes(syl.onset)) return true;
  // R3: e terbuka pada suku akhir kata ≥2 suku → taling (tauke, sake, karaoke)
  if (syl.isOpen && syl.isLast) { try { if (syllabify(globalWord).length>=2) return true; } catch(e) {} }
  return false;
}

// ---------- 5. Aturan Alif untuk 'a' (merangkum §8.2—9.3 pedoman) ----------
function needAlifForA(syllables, idx, globalWord) {
  const syl = syllables[idx];
  if (syl.vowel !== 'a') return null;
  const isOpen = syl.isOpen;
  const n = syllables.length;
  if (!isOpen) return false;
  if (n === 1) return true;
  const lastOnset = syllables[n-1].onset;
  const lastIsKafGa = (lastOnset === 'k' || lastOnset === 'g');
  const lastIsDalRa = ['d','r','l','w','ng'].includes(lastOnset);
  if (n === 2) {
    const s0 = syllables[0], s1 = syllables[1];
    const bothOpen = s0.isOpen && s1.isOpen;
    const closedOpen = !s0.isOpen && s1.isOpen;
    const openClosed = s0.isOpen && !s1.isOpen;
    const bothClosed = !s0.isOpen && !s1.isOpen;
    if (bothOpen) {
      if (s0.vowel === 'e' && !isTaling(globalWord, s0)) return true;
      if (lastIsKafGa) return idx === 0;
      if (lastIsDalRa) return true;
      return idx === 0;
    }
    if (closedOpen) {
      if (s0.vowel === 'e' && !isTaling(globalWord, s0)) return true;
      if (lastIsKafGa) return false;
      return idx === 1;
    }
    if (openClosed) {
      if (idx === 1) return false;
      if (s0.vowel === 'e' && !isTaling(globalWord, s0)) return false;
      return true;
    }
    if (bothClosed) return false;
  }
  if (n >= 3) {
    if (idx === 0) return syl.onset !== ''; // v9: 'a' suku-0 beronset → alif (gabenor, kabinet)
    if (idx < n-2) return false;
    const penult = syllables[n-2];
    const last = syllables[n-1];
    const bothOpenLast = penult.isOpen && last.isOpen;
    const closedOpenLast = !penult.isOpen && last.isOpen;
    const openClosedLast = penult.isOpen && !last.isOpen;
    const bothClosedLast = !penult.isOpen && !last.isOpen;
    const praPepetLast = penult.vowel === 'e' && !isTaling(globalWord, penult);
    if (bothOpenLast) {
      if (praPepetLast) return true;
      if (lastIsKafGa) return idx === n-2;
      if (lastIsDalRa) return true;
      return idx === n-2;
    }
    if (closedOpenLast) {
      if (praPepetLast) return true;
      if (lastIsKafGa) return false;
      return idx === n-1;
    }
    if (openClosedLast) {
      if (idx === n-1) return false;
      if (praPepetLast) return false;
      return true;
    }
    if (bothClosedLast) return false;
  }
  return true;
}

// ---------- 6. Konsonan ke Jawi ----------
function consonantToJawiCons(str) {
  if (!str) return "";
  // str boleh "ng", "ny", "bl" cluster etc
  // Jika digraf known, map directly
  if (JAWI[str]) return JAWI[str];
  // Jika cluster 2 huruf seperti "bl": map per huruf
  let out = "";
  let i=0;
  while (i<str.length) {
    let two = str.substr(i,2);
    if (JAWI[two]) { out += JAWI[two]; i+=2; }
    else { out += JAWI[str[i]] || str[i]; i+=1; }
  }
  return out;
}

// ---------- 7. Utama: Rumi -> Jawi per suku ----------
function syllableToJawi(syl, idx, allSyls, globalWord) {
  let vowel = syl.vowel;
  // Kosong (should not happen)
  if (!vowel) {
    return consonantToJawiCons(syl.onset) + consonantToJawiCons(syl.coda);
  }

  // HAMZAH 0 — KVVK hamzah dimatikan (semua hamzah via EXC)

  // Onset Jawi
  let onsetJ = consonantToJawiCons(syl.onset);
  let hasOnset = syl.onset !== "";

  // Vokal Jawi
  let vowelJ = "";
  const isFirstSyll = idx===0;
  // Perhatikan: vokal awal yang tanpa onset perlu alif. Jika ada onset, vokal medial tidak perlu alif awal.
  // Jadi cek hasOnset, bukan isFirstSyll semata.

  if (vowel === "a") {
    let needAlif = needAlifForA(allSyls, idx, globalWord);
    // Jika tidak ada onset dan vokal a, tetap perlu alif (ada → ادا)
    if (!hasOnset && idx>0 && allSyls[idx-1].vowel==="a") {
      vowelJ = "ء"; // v10: a + a tanpa onset → hamzah (binaan→بيناءن, kenyataan→کڽاتاءن, bacaan→باچاءن)
    } else if (!hasOnset) {
      vowelJ = "ا"; // a awal tanpa onset selalu alif
      // Jika needAlif false untuk KVK? tapi a awal tanpa onset & terbuka? tetap alif
    } else if (needAlif) {
      vowelJ = "ا";
    } else {
      vowelJ = "";
    }
  } else if (vowel === "i") {
    if (!hasOnset) vowelJ = "اي"; // i awal tanpa onset: alif-ya
    else vowelJ = "ي";
  } else if (vowel === "é") {
    if (!hasOnset) vowelJ = "اي";
    else vowelJ = "ي";
  } else if (vowel === "e") {
    let taling = isTaling(globalWord, syl);
    if (taling) {
      if (!hasOnset) vowelJ = "اي";
      else vowelJ = "ي";
    } else {
      // pepet
      if (!hasOnset) vowelJ = "ا"; // pepet awal tanpa onset → alif saja (emas → امس)
      else if (syl.isLast && syl.isOpen) vowelJ = "ى"; // akhir terbuka pepet → ى (metode)
      else vowelJ = ""; // medial pepet tidak tulis
    }
  } else if (vowel === "o") {
    if (!hasOnset) vowelJ = "او";
    else vowelJ = "و";
  } else if (vowel === "u") {
    if (!hasOnset) vowelJ = "او";
    else vowelJ = "و";
  } else if (vowel === "ai" || vowel === "ae") {
    // HAMZAH v10 (data PRPM): diftong TERTUTUP → اءي (baik→باءيق); terbuka → اي (sampai→سمڤاي); ai tanpa onset → اءي
    vowelJ = (!syl.isOpen || !hasOnset) ? "اءي" : "اي";
  } else if (vowel === "au") {
    vowelJ = (!syl.isOpen || !hasOnset) ? "اءو" : "او";
  } else if (vowel === "oi") {
    vowelJ = (!syl.isOpen || !hasOnset) ? "ءاوي" : "واي";
  }

  let out;
  if (vowel === "a" && vowelJ === "") {
    out = onsetJ; // hanya konsonan onset, tanpa alif
  } else if (!hasOnset) {
    // tanpa onset, vokal sudah termasuk alif jika perlu
    out = vowelJ;
  } else {
    out = onsetJ + vowelJ;
  }

  // Coda
  if (syl.coda) {
    let coda = syl.coda;
    // final k → qaf jika tertutup dan di akhir kata (Melayu jati)
    // tapi jika sukukatanya bukan akhir? mis "makna" m a k n a: k adalah coda suku pertama? "mak" tertutup tapi bukan akhir kata → tetap ك ? pedoman: k tengah = ك , k akhir tertutup = ق
    let isLastSyll = idx === allSyls.length-1;
    // cluster coda seperti "ng" already handled via consonantToJawiCons
    // Need to handle single k vs q
    if (coda === "k" && isLastSyll) {
      let lowQaf=globalWord.toLowerCase();
      const kafSet=new Set(["objek","projek","subjek","dek","blok","plastik","unik","muzik","politik","bank","klinik","teknik","elektrik","logik","fizik","matematik","antik","automatik","kritik","logik","trafik","stik","plak","cek","rekod"]);
      if(kafSet.has(lowQaf) || /(ek|ik)$/.test(lowQaf) && lowQaf.length>5 && /[jv]/.test(lowQaf)){
        out += "ک";
      } else if(lowQaf.endsWith('ek') || lowQaf.endsWith('ik') || lowQaf.endsWith('ok')){
        // Untuk loan umum, cek 10000: kebanyakan -ik adalah qaf kecuali yang jelas pinjaman
        // Sementara tetap qaf untuk selamat (240 vs 22, qaf lebih dominan)
        out += "ق";
      } else {
        out += "ق";
      }
    } else {
      out += consonantToJawiCons(coda);
    }
  }
  return out;
}

