// Build REVERSE_DICT from EXCEPTION_DICT (Jawi -> Latin, first wins)
const REVERSE_DICT = {};
for (let [lat,j] of Object.entries(EXCEPTION_DICT)) {
  if (!REVERSE_DICT[j]) REVERSE_DICT[j]=lat;
}

// Fallback heuristic for Jawi->Rumi (when not in dicts)
// - و after cons -> 'o' (default), ي after cons -> 'i', ا->a, ى->e
// - Insert 'e' between two consonants without vowel letter (pepet) and 'a' before final ه etc when needed
const REVERSE_MAP = {
  'ا': 'a', 'ب': 'b', 'ت': 't', 'ة': 't', 'ث': 's', 'ج': 'j', 'چ': 'c', 'ح': 'h', 'خ': 'kh',
  'د': 'd', 'ذ': 'z', 'ر': 'r', 'ز': 'z', 'س': 's', 'ش': 'sy',
  'ص': 's', 'ض': 'd', 'ط': 't', 'ظ': 'z', 'ع': '', 'غ': 'gh',
  'ڠ': 'ng', 'ف': 'f', 'ڤ': 'p', 'ق': 'k', 'ك': 'k', 'ڬ': 'g', 'ل': 'l',
  'م': 'm', 'ن': 'n', 'و': 'w', 'ۏ': 'v', 'ه': 'h', 'ء': "'", 'ي': 'y', 'ى': 'e', 'ڽ': 'ny'
};
function heurJawiToRumi(jawi) {
  const consMap = {
    'ب':'b','ت':'t','ة':'t','ث':'s','ج':'j','چ':'c','ح':'h','خ':'kh','د':'d','ذ':'z','ر':'r','ز':'z','س':'s','ش':'sy','ص':'s','ض':'d','ط':'t','ظ':'z','ع':'','غ':'gh','ڠ':'ng','ف':'f','ڤ':'p','ق':'k','ك':'k','ڬ':'g','ل':'l','م':'m','ن':'n','ه':'h','ڽ':'ny','ء':"'",'ۏ':'v'
  };
  const vowelSet = new Set(['ا','و','ي','ى']);
  let out='';
  for(let i=0;i<jawi.length;i++){
    let ch=jawi[i];
    if(ch==='ا'){ out+='a'; }
    else if(ch==='ى'){ out+='e'; }
    else if(ch==='و'){ out+=(i===0?'w':'o'); }
    else if(ch==='ي'){ out+=(i===0?'y':'i'); }
    else if(consMap[ch]){
      out+=consMap[ch];
      let next=jawi[i+1];
      if(next && !vowelSet.has(next) && consMap[next]){
        let isBeforeLast=(i+1===jawi.length-1);
        out+=(isBeforeLast?'a':'e');
      }
    } else {
      out+=ch;
    }
  }
  out=out.replace(/aa+/g,'a');
  return out;
}
function jawiToRumi(jawi) {
  if (!jawi) return "";
  // Exact dict hits first (500 manual)
  if (REVERSE_DICT[jawi]) return REVERSE_DICT[jawi];
  if (JAWI_TO_LATIN_AUTO[jawi]) return JAWI_TO_LATIN_AUTO[jawi];
  return heurJawiToRumi(jawi);
}

function latinToJawi(text) {
  return text.split(/(\s+|[.,!?;:"'()])/g).map(tok => {
    if (/^\s+$/.test(tok) || /^[.,!?;:"'()]$/.test(tok) || /^\d+$/.test(tok)) return tok;
    if (tok.includes('-') || tok.includes('/')) {
      return tok.split(/([-\/])/g).map(p => {
        if (p==='-'||p==='/') return p;
        return wordToJawi(p);
      }).join('');
    }
    return wordToJawi(tok);
  }).join('');
}
function jawiToLatin(text) {
  // keep punctuation/symbols, handle hyphen
  return text.split(/(\s+|[.,!?;:"'()])/g).map(tok => {
    if (/^\s+$/.test(tok) || /^[.,!?;:"'()]$/.test(tok) || /^\d+$/.test(tok)) return tok;
    if (tok.includes('-') || tok.includes('/')) {
      return tok.split(/([-\/])/g).map(p => {
        if (p==='-'||p==='/') return p;
        return jawiToRumi(p);
      }).join('');
    }
    return jawiToRumi(tok);
  }).join('');
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = { latinToJawi, jawiToLatin, wordToJawi, syllabify, jawiToRumi, heurJawiToRumi, EXCEPTION_DICT, TALING_DICT, JAWI_TO_LATIN_AUTO, REVERSE_DICT };
}
if (typeof window !== 'undefined') {
  window.JawiConverter = { latinToJawi, jawiToLatin, wordToJawi, syllabify, jawiToRumi };
}
